        _newShipment.ShippedDate = DateTime.UtcNow;
        _newShipment.EstimatedDelivery = DateTime.UtcNow.AddDays(5);
        _newShipment.Status = ShipmentStatus.Pending;

        var created = await ShipmentService.CreateShipmentAsync(_newShipment);
        _shipments.Insert(0, created);
        _newShipment = new();
        _showCreateForm = false;
    }

    private async Task UpdateStatus(int id, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var status))
        {
            var updated = await ShipmentService.UpdateShipmentStatusAsync(id, status);
            var index = _shipments.FindIndex(s => s.Id == id);
            if (index >= 0) _shipments[index] = updated;
        }
    }

