        (string.IsNullOrEmpty(_filterText) || s.Destination.Contains(_filterText, StringComparison.OrdinalIgnoreCase)) &&
        (string.IsNullOrEmpty(_statusFilter) || s.Status.ToString() == _statusFilter));

