}

using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServerService : IShipmentService
{
    private readonly ApplicationDbContext _db;

    public ShipmentServerService(ApplicationDbContext db)
    {
        _db = db;
    }

    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await _db.Shipments.Select(s => MapToDto(s)).ToListAsync();
    }

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var entity = await _db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return entity is null ? null : MapToDto(entity);
    }

    public async Task<List<ShipmentDto>> GetShipmentsByCustomerAsync(string customerEmail)
    {
        return await _db.Shipments
            .Where(s => s.CustomerEmail == customerEmail)
            .Select(s => MapToDto(s))
            .ToListAsync();
    }

    public async Task<ShipmentDto> CreateShipmentAsync(ShipmentDto dto)
    {
        var entity = new Shipment
        {
            TrackingNumber = dto.TrackingNumber,
            Origin = dto.Origin,
            Destination = dto.Destination,
            Status = dto.Status,
            ShippedDate = dto.ShippedDate,
            EstimatedDelivery = dto.EstimatedDelivery,
            CustomerEmail = dto.CustomerEmail,
            Description = dto.Description
        };
        _db.Shipments.Add(entity);
        await _db.SaveChangesAsync();
        return MapToDto(entity);
    }

    public async Task<ShipmentDto> UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var entity = await _db.Shipments.FindAsync(id) ?? throw new InvalidOperationException("Shipment not found");
        entity.Status = status;
        await _db.SaveChangesAsync();
        return MapToDto(entity);
    }

    private static ShipmentDto MapToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status,
        ShippedDate = s.ShippedDate,
        EstimatedDelivery = s.EstimatedDelivery,
        CustomerEmail = s.CustomerEmail,
        Description = s.Description
    };
}

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("/", async (IShipmentService service) =>
            Results.Ok(await service.GetAllShipmentsAsync()));

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
        {
            var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
            return shipment is null ? Results.NotFound() : Results.Ok(shipment);
        });

        group.MapGet("/customer/{customerEmail}", async (string customerEmail, IShipmentService service) =>
            Results.Ok(await service.GetShipmentsByCustomerAsync(customerEmail)));

        group.MapPost("/", async (ShipmentDto dto, IShipmentService service) =>
        {
            var created = await service.CreateShipmentAsync(dto);
            return Results.Created($"api/shipments/track/{created.TrackingNumber}", created);
        });

        group.MapPut("/{id}/status", async (int id, ShipmentStatus status, IShipmentService service) =>
        {
            var updated = await service.UpdateShipmentStatusAsync(id, status);
            return Results.Ok(updated);
        });
    }
}

