@page "/"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Dashboard - ShipmentTracker</PageTitle>

<h1>Shipment Dashboard</h1>

@if (_loading)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <div class="row mb-3">
        <div class="col">
            <div class="card text-bg-primary">
                <div class="card-body">
                    <h5 class="card-title">Total Shipments</h5>
                    <p class="card-text display-6">@_shipments.Count</p>
                </div>
            </div>
        </div>
        <div class="col">
            <div class="card text-bg-warning">
                <div class="card-body">
                    <h5 class="card-title">In Transit</h5>
                    <p class="card-text display-6">@_shipments.Count(s => s.Status == ShipmentStatus.InTransit)</p>
                </div>
            </div>
        </div>
        <div class="col">
            <div class="card text-bg-success">
                <div class="card-body">
                    <h5 class="card-title">Delivered</h5>
                    <p class="card-text display-6">@_shipments.Count(s => s.Status == ShipmentStatus.Delivered)</p>
                </div>
            </div>
        </div>
        <div class="col">
            <div class="card text-bg-danger">
                <div class="card-body">
                    <h5 class="card-title">Exceptions</h5>
                    <p class="card-text display-6">@_shipments.Count(s => s.Status == ShipmentStatus.Exception)</p>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private List<ShipmentDto> _shipments = [];
    private bool _loading = true;

    protected override async Task OnInitializedAsync()
    {
        _shipments = await ShipmentService.GetAllShipmentsAsync();
        _loading = false;
    }
}

@page "/shipments"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>All Shipments - ShipmentTracker</PageTitle>

<h1>Shipments</h1>

<div class="row mb-3">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Filter by destination..."
               @bind="_filterText" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="_statusFilter">
            <option value="">All Statuses</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button class="btn btn-primary" @onclick="ShowCreateForm">
            + New Shipment
        </button>
    </div>
</div>

@if (_showCreateForm)
{
    <div class="card mb-3">
        <div class="card-body">
            <h5>Create New Shipment</h5>
            <div class="row g-2">
                <div class="col-md-3">
                    <input class="form-control" placeholder="Origin" @bind="_newShipment.Origin" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Destination" @bind="_newShipment.Destination" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Customer Email" @bind="_newShipment.CustomerEmail" />
                </div>
                <div class="col-md-3">
                    <input class="form-control" placeholder="Description" @bind="_newShipment.Description" />
                </div>
            </div>
            <div class="mt-2">
                <button class="btn btn-success btn-sm" @onclick="CreateShipment">Create</button>
                <button class="btn btn-secondary btn-sm" @onclick="() => _showCreateForm = false">Cancel</button>
            </div>
        </div>
    </div>
}

@if (_loading)
{
    <p><em>Loading...</em></p>
}
else
{
    <table class="table table-striped table-hover">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Origin</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Shipped</th>
                <th>Est. Delivery</th>
                <th>Actions</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var shipment in FilteredShipments)
            {
                <tr>
                    <td><code>@shipment.TrackingNumber</code></td>
                    <td>@shipment.Origin</td>
                    <td>@shipment.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                    <td>@shipment.ShippedDate.ToString("yyyy-MM-dd")</td>
                    <td>@shipment.EstimatedDelivery.ToString("yyyy-MM-dd")</td>
                    <td>
                        <select class="form-select form-select-sm" style="width:auto;display:inline-block"
                                @onchange="e => UpdateStatus(shipment.Id, e)">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status" selected="@(status == shipment.Status)">@status</option>
                            }
                        </select>
                    </td>
                </tr>
            }
        </tbody>
    </table>

    @if (!FilteredShipments.Any())
    {
        <p class="text-muted">No shipments match your filter.</p>
    }
}

@code {
    private List<ShipmentDto> _shipments = [];
    private bool _loading = true;
    private string _filterText = string.Empty;
    private string _statusFilter = string.Empty;
    private bool _showCreateForm;
    private ShipmentDto _newShipment = new();

    private IEnumerable<ShipmentDto> FilteredShipments => _shipments.Where(s =>
        (string.IsNullOrEmpty(_filterText) || s.Destination.Contains(_filterText, StringComparison.OrdinalIgnoreCase)) &&
        (string.IsNullOrEmpty(_statusFilter) || s.Status.ToString() == _statusFilter));

    protected override async Task OnInitializedAsync()
    {
        _shipments = await ShipmentService.GetAllShipmentsAsync();
        _loading = false;
    }

    private void ShowCreateForm() => _showCreateForm = true;

    private async Task CreateShipment()
    {
        _newShipment.TrackingNumber = $"TRK-{Guid.NewGuid().ToString()[..8].ToUpper()}";
        _newShipment.ShippedDate = DateTime.UtcNow;
        _newShipment.EstimatedDelivery = DateTime.UtcNow.AddDays(5);
        _newShipment.Status = ShipmentStatus.Pending;

        var created = await ShipmentService.CreateShipmentAsync(_newShipment);
        _shipments.Insert(0, created);
        _newShipment = new();
        _showCreateForm = false;
    }

    private async Task UpdateStatus(int id, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var status))
        {
            var updated = await ShipmentService.UpdateShipmentStatusAsync(id, status);
            var index = _shipments.FindIndex(s => s.Id == id);
            if (index >= 0) _shipments[index] = updated;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "text-bg-secondary",
        ShipmentStatus.PickedUp => "text-bg-info",
        ShipmentStatus.InTransit => "text-bg-warning",
        ShipmentStatus.OutForDelivery => "text-bg-primary",
        ShipmentStatus.Delivered => "text-bg-success",
        ShipmentStatus.Exception => "text-bg-danger",
        _ => "text-bg-light"
    };
}

@page "/track"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment - ShipmentTracker</PageTitle>

<h1>Track Your Shipment</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., TRK-A1B2C3D4)"
                   @bind="_trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchShipment">Track</button>
        </div>
    </div>
</div>

@if (_searching)
{
    <p><em>Searching...</em></p>
}
else if (_searched && _shipment is null)
{
    <div class="alert alert-warning">No shipment found with tracking number <strong>@_searchedNumber</strong>.</div>
}
else if (_shipment is not null)
{
    <div class="card">
        <div class="card-header">
            <h5 class="mb-0">Tracking: <code>@_shipment.TrackingNumber</code></h5>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Status</dt>
                        <dd><span class="badge @GetStatusBadgeClass(_shipment.Status) fs-6">@_shipment.Status</span></dd>
                        <dt>Description</dt>
                        <dd>@_shipment.Description</dd>
                        <dt>Origin</dt>
                        <dd>@_shipment.Origin</dd>
                        <dt>Destination</dt>
                        <dd>@_shipment.Destination</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>Shipped Date</dt>
                        <dd>@_shipment.ShippedDate.ToString("MMMM dd, yyyy")</dd>
                        <dt>Estimated Delivery</dt>
                        <dd class="fs-5 fw-bold text-primary">@_shipment.EstimatedDelivery.ToString("MMMM dd, yyyy")</dd>
                    </dl>
                </div>
            </div>

            <h6 class="mt-3">Shipment Progress</h6>
            <div class="progress" style="height: 30px;">
                <div class="progress-bar @GetProgressBarClass(_shipment.Status)"
                     style="width: @GetProgressPercent(_shipment.Status)%">
                    @_shipment.Status
                </div>
            </div>
        </div>
    </div>
}

<hr class="my-4" />

<h3>My Shipments</h3>
@if (_myShipments.Any())
{
    <table class="table">
        <thead>
            <tr>
                <th>Tracking #</th>
                <th>Destination</th>
                <th>Status</th>
                <th>Est. Delivery</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var s in _myShipments)
            {
                <tr @onclick="() => TrackExisting(s.TrackingNumber)" style="cursor:pointer">
                    <td><code>@s.TrackingNumber</code></td>
                    <td>@s.Destination</td>
                    <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                    <td>@s.EstimatedDelivery.ToString("yyyy-MM-dd")</td>
                </tr>
            }
        </tbody>
    </table>
}
else
{
    <p class="text-muted">No shipments associated with your account yet.</p>
}

@code {
    private string _trackingNumber = string.Empty;
    private string _searchedNumber = string.Empty;
    private ShipmentDto? _shipment;
    private bool _searching;
    private bool _searched;
    private List<ShipmentDto> _myShipments = [];

    [CascadingParameter]
    private Task<AuthenticationState>? AuthStateTask { get; set; }

    protected override async Task OnInitializedAsync()
    {
        if (AuthStateTask is not null)
        {
            var authState = await AuthStateTask;
            var email = authState.User.Identity?.Name ?? string.Empty;
            if (!string.IsNullOrEmpty(email))
            {
                _myShipments = await ShipmentService.GetShipmentsByCustomerAsync(email);
            }
        }
    }

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(_trackingNumber)) return;
        _searching = true;
        _searched = false;
        _shipment = null;
        _searchedNumber = _trackingNumber.Trim();
        _shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(_searchedNumber);
        _searching = false;
        _searched = true;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await SearchShipment();
    }

    private void TrackExisting(string trackingNumber)
    {
        _trackingNumber = trackingNumber;
        _ = SearchShipment();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "text-bg-secondary",
        ShipmentStatus.PickedUp => "text-bg-info",
        ShipmentStatus.InTransit => "text-bg-warning",
        ShipmentStatus.OutForDelivery => "text-bg-primary",
        ShipmentStatus.Delivered => "text-bg-success",
        ShipmentStatus.Exception => "text-bg-danger",
        _ => "text-bg-light"
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Exception => "bg-danger",
        ShipmentStatus.Delivered => "bg-success",
        _ => "bg-primary"
    };

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 25,
        ShipmentStatus.InTransit => 50,
        ShipmentStatus.OutForDelivery => 75,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Exception => 50,
        _ => 0
    };
}

